	    // Bits: 127x1 1x0 62x1 1x0 1x1
	    const {red} = x1;
	    const r0 = this.core(x1);
	    const r1 = red.sqrn(r0, 1);
	    const r2 = red.sqrnmul(r1, 1, x1);

	    return r2;
