	    // Bits: 223x1 1x0 222x1 1x0 1x1
	    const {red} = x1;
	    const r0 = this.pm3d4(x1);
	    const r1 = red.sqrn(r0, 1);
	    const r2 = red.sqrnmul(r1, 1, x1);

